import { Button, Flex, Typography } from 'antd';

import DeleteIcon from 'assets/images/icons/delete.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import { PostbackStatus, PostbackTableLink } from 'entities/Postback';
import { EMainRoutes, EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

import { IPostback } from '../model/types';

export const getPostback = (postback: IPostback, key: number, onDelete: () => void) => {
	const { uuid, action_statuses } = postback;

	const params = !postback.data ? [] : Object.keys(postback.data).join(', ');

	return {
		key,
		uuid: (
			<Typography.Text ellipsis={{ tooltip: uuid }} style={{ maxWidth: 70 }}>
				{uuid}
			</Typography.Text>
		),
		source: (
			<Typography.Text ellipsis={{ tooltip: postback?.source?.name }} style={{ maxWidth: 200 }}>
				{postback?.source?.name || '-'}
			</Typography.Text>
		),
		action_statuses: <PostbackStatus statuses={action_statuses} />,
		url: <PostbackTableLink data={postback} />,
		params: (
			<Typography.Text type="secondary" ellipsis={{ tooltip: params }} style={{ maxWidth: 200 }}>
				{params}
			</Typography.Text>
		),
		buttons: (
			<Flex gap={8}>
				<ButtonStyleLink
					type="default"
					size="small"
					icon={<EditIcon />}
					to={`/${EMainRoutes.TOOLS}/${EMainRoutes.POSTBACKS}/${EMainRoutes.EDIT}/${uuid}`}
					onClick={() =>
						sendYmEvent({
							event: EYmEvents.CLICK_EDIT_POSTBACK,
							o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.INSTRUMENTS],
							o2: EYmEventsO2.POSTBACK,
							si: postback.uuid,
							wi: postback.source?.uuid,
						})
					}
				/>
				<Button
					size="small"
					variant="text"
					color="danger"
					onClick={() => {
						sendYmEvent({
							event: EYmEvents.CLICK_DELETE_POSTBACK,
							o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.INSTRUMENTS],
							o2: EYmEventsO2.POSTBACK,
							si: postback.uuid,
							wi: postback.source?.uuid,
						});
						onDelete();
					}}
					icon={<DeleteIcon />}></Button>
			</Flex>
		),
	};
};
