import { FC, HTMLAttributes, ReactNode, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, Table, TableColumnsType } from 'antd';

import { IPostback, useGetPostbackListQuery } from 'entities/Postback';
import { DeletePostbackModal } from 'entities/Postback/ui/DeletePostbackModal/DeletePostbackModal';
import { getPostback } from 'entities/Postback/utils/getPostback';
import { PosbackFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { getDefaultSortOrder, getTableSorter } from 'shared/utils';

interface DataType {
	key: React.Key;
	uuid: ReactNode;
	source: ReactNode;
	action_statuses: ReactNode;
	url: ReactNode;
	params: ReactNode;
	buttons: ReactNode;
}

interface IPostbackListProps extends HTMLAttributes<HTMLDivElement> {}

export const PostbackList: FC<IPostbackListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [deletingPostback, setDeletingPostback] = useState<IPostback | null>(null);
	const [searchParams, setSearchParams] = useSearchParams();
	const { data, isFetching } = useGetPostbackListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;

	const columns: TableColumnsType<DataType> = [
		{
			dataIndex: 'uuid',
			key: 'uuid',
			title: `ID`,
		},
		{
			dataIndex: 'source',
			key: 'source',
			title: t('Площадка'),
			defaultSortOrder: getDefaultSortOrder('source', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'action_statuses',
			key: 'action_statuses',
			title: t('Статус действия'),
		},
		{
			dataIndex: 'url',
			key: 'url',
			title: t('Ссылка с токеном'),
		},
		{
			dataIndex: 'params',
			key: 'params',
			title: t('Параметры'),
		},
		{
			dataIndex: 'buttons',
			key: 'buttons',
			width: 80,
		},
	];

	const dataSource = hasData
		? data?.results?.map<DataType>((postback, i) => {
				return getPostback(postback, i, () => setDeletingPostback(postback));
			})
		: [];

	return (
		<Flex vertical gap={20} {...props} className={className}>
			<PosbackFilters style={{ marginBottom: 4 }} />

			{isFetching && <OverlayLoader />}

			{!hasData && !isFetching && <EmptyState title={t('Postback пока не найдено')} />}

			{hasData && (
				<>
					<Table<DataType>
						columns={columns}
						dataSource={dataSource}
						bordered={false}
						scroll={{ x: 'max-content' }}
						pagination={false}
						showSorterTooltip={false}
						onChange={getTableSorter<DataType>(searchParams, setSearchParams)}
					/>

					<Pagination count={data?.count || 1} />
				</>
			)}

			<DeletePostbackModal postback={deletingPostback} setDeletingPostback={setDeletingPostback} />
		</Flex>
	);
};
