import { HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Input } from 'antd';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import { EFilters, useFilters } from 'features/Filters';
import { useMedia } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';

export interface IPosbackFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const PosbackFilters = ({ ...props }: IPosbackFiltersProps) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const { onFilterChange, getFilterValue } = useFilters();

	return (
		<Flex {...props} vertical={isMd} justify="space-between" gap={16}>
			<Input
				placeholder={t('Поиск по параметру')}
				value={getFilterValue(EFilters.SEARCH_ID) || ''}
				onChange={(e) => onFilterChange(EFilters.SEARCH_ID, e.target.value)}
				allowClear
				style={{ maxHeight: 40, width: isMd ? '100%' : 200 }}
			/>

			<ButtonStyleLink
				type="primary"
				block={isMd}
				icon={<PlusIcon width={16} height={16} />}
				to={`/${EMainRoutes.TOOLS}/${EMainRoutes.POSTBACKS}/${EMainRoutes.CREATE}`}>
				{t('Добавить Postback')}
			</ButtonStyleLink>
		</Flex>
	);
};

export default PosbackFilters;
