import { FC } from 'react';

import { LinkProps } from 'antd/lib/typography/Link';

import { EpostbackParams, IPostback } from 'entities/Postback/model/types';
import { EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { CopyLink } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

interface IPostbackTableLinkProps extends LinkProps {
	data: IPostback;
}

export const PostbackTableLink: FC<IPostbackTableLinkProps> = ({ data }) => {
	const createURL = () => {
		try {
			const url = new URL(data.url);

			data.data &&
				Object.keys(data.data).forEach((key) => {
					url.searchParams.set(key, data.data ? data.data[key as EpostbackParams] : key);
				});

			return decodeURI(url.toString());
		} catch (e) {
			return '';
		}
	};

	return (
		<CopyLink
			url={createURL()}
			onLinkCopy={() =>
				sendYmEvent({
					event: EYmEvents.CLICK_COPY_LINK_TOKEN,
					o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.INSTRUMENTS],
					o2: EYmEventsO2.POSTBACK,
					o4: createURL(),
					si: data.uuid,
					wi: data.source?.uuid,
				})
			}
		/>
	);
};
