import { FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Modal, ModalProps, Typography } from 'antd';

import { useDeletePostbackMutation } from 'entities/Postback/api/api';
import { IPostback } from 'entities/Postback/model/types';

interface IDeletePostbackModalProps extends ModalProps {
	postback: IPostback | null;
	setDeletingPostback: (source: IPostback | null) => void;
}

export const DeletePostbackModal: FC<IDeletePostbackModalProps> = ({ postback, setDeletingPostback, ...props }) => {
	const { t } = useTranslation();

	const [deletePostback, { isLoading, isSuccess }] = useDeletePostbackMutation();

	useEffect(() => {
		if (isSuccess) {
			setDeletingPostback(null);
		}
	}, [isSuccess]); // eslint-disable-line

	if (!postback) return null;

	return (
		<Modal
			{...props}
			open={!!postback}
			footer={null}
			closable={true}
			maskClosable={true}
			onCancel={() => setDeletingPostback(null)}>
			<Flex vertical gap={24}>
				<Typography.Title level={4} style={{ margin: 0 }}>
					{t('Удалить Postback?')}
				</Typography.Title>

				<Typography.Text type="secondary" style={{ fontSize: 16 }}>
					{t('Код оптимизации будет безвозвратно удален.')}
				</Typography.Text>

				<Flex justify="space-between">
					<Button onClick={() => setDeletingPostback(null)}>{t('Отменить')}</Button>
					<Button
						variant="solid"
						color="danger"
						loading={isLoading}
						disabled={isLoading}
						onClick={() => deletePostback(postback.uuid)}>
						{t('Удалить')}
					</Button>
				</Flex>
			</Flex>
		</Modal>
	);
};
