import { FC } from 'react';

import { Typography } from 'antd';
import { TextProps } from 'antd/lib/typography/Text';

import { EPostbackStatuses } from 'entities/Postback/model/types';
import { useTrans } from 'shared/hooks';

interface IPostbackStatusProps extends TextProps {
	statuses: EPostbackStatuses[];
}

export const PostbackStatus: FC<IPostbackStatusProps> = ({ statuses, ...props }) => {
	const { postbackStatuses } = useTrans();
	const status = statuses
		.map((status, i) => (i > 0 ? postbackStatuses[status].toLocaleLowerCase() : postbackStatuses[status] || status))
		.join(', ');

	return (
		<Typography.Text {...props} ellipsis={{ tooltip: status }} style={{ maxWidth: 200 }}>
			{status}
		</Typography.Text>
	);
};
